#include <stdio.h>
#include <stdint.h>

#define BIT(k)        (1u << (k))
#define SET(x, k)     ((x) |= BIT(k))
#define CLEAR(x, k)   ((x) &= ~BIT(k))
#define TOGGLE(x, k)  ((x) ^= BIT(k))
#define TEST(x, k)    (((x) >> (k)) & 1u)

int main(void) {
    uint32_t x = 0;
    SET(x, 3); SET(x, 0);              /* 0b1001 = 9 */
    TOGGLE(x, 1);                      /* 0b1011 = 11 */
    CLEAR(x, 0);                       /* 0b1010 = 10 */
    printf("%u %u %u\n", x, TEST(x, 3), TEST(x, 2));  /* 10 1 0 */

    /* extract a w-bit field starting at bit s */
    uint32_t reg = 0xABCD1234u;
    unsigned s = 8, w = 8;
    printf("%x\n", (reg >> s) & ((1u << w) - 1u));      /* 12 */
    return 0;
}

static inline uint64_t set64(uint64_t x, unsigned k)   { return x |  (1ULL << k); }
static inline uint64_t clr64(uint64_t x, unsigned k)   { return x & ~(1ULL << k); }
static inline int      test64(uint64_t x, unsigned k)  { return (x >> k) & 1; }

uint32_t get(uint32_t x, unsigned s, unsigned w) {
    return (x >> s) & (~0u >> (32 - w));
}
uint32_t put(uint32_t x, unsigned s, unsigned w, uint32_t v) {
    uint32_t m = (~0u >> (32 - w)) << s;
    return (x & ~m) | ((v << s) & m);
}

static inline uint32_t rotl32(uint32_t x, unsigned n) {
    n &= 31;
    return (x << n) | (x >> ((32 - n) & 31));
}

int popcount(uint32_t x) {
    int n = 0;
    while (x) { x &= x - 1; n++; }
    return n;
}
int ilog2(uint32_t x) { return 31 - __builtin_clz(x); }  /* x > 0 */

int single(const int *a, int n) {
    int r = 0;
    for (int i = 0; i < n; i++) r ^= a[i];
    return r;
}

